import { loadNative } from '../mochinode/index.js';
import { MochiBuffer as Buffer } from '../mochibuffer/index.js';

let native = null;
let nativeFailure = null;

try {
    // Preferred: mochiossil (OpenSSL EVP backend, cross-platform .dll/.so).
    native = await loadNative('mochiossil');
} catch (_ossl) {
    try {
        // Fallback: mochicrypto (BCrypt, Windows-only).
        native = await loadNative('mochicrypto');
    } catch (error) {
        nativeFailure = error;
    }
}

function ensureNative() {
    if (native) return native;
    throw new Error(`mochicrypto: native plugin unavailable: ${nativeFailure ? nativeFailure.message : 'not loaded'}`);
}

function toBytes(value) {
    if (value && typeof value.export === 'function' && value.type === 'secret') return value.export({ format: 'buffer' });
    if (value && value._buf instanceof Uint8Array) return value._buf;
    if (value instanceof Uint8Array) return value;
    if (value === undefined || value === null) return new Uint8Array(0);
    if (typeof value === 'string') return Buffer.from(value, 'utf8');
    if (Array.isArray(value)) return Uint8Array.from(value);
    if (value.buffer instanceof ArrayBuffer) return new Uint8Array(value.buffer, value.byteOffset || 0, value.byteLength);
    if (typeof value === 'number') {
        const out = new Uint8Array(8);
        new DataView(out.buffer).setFloat64(0, value);
        return out;
    }
    return Buffer.from(value);
}

function toHex(value) {
    return Buffer.from(toBytes(value)).toString('hex');
}

function fromHex(value) {
    return Buffer.from(String(value || ''), 'hex');
}

function digestName(name) {
    const key = String(name || 'sha256').toLowerCase().replace(/[-_]/g, '');
    if (key === 'md5') return 'md5';
    if (key === 'sha1') return 'sha1';
    if (key === 'sha224') return 'sha256';
    if (key === 'sha256') return 'sha256';
    if (key === 'sha384') return 'sha384';
    if (key === 'sha512') return 'sha512';
    throw new Error(`mochicrypto: unsupported digest '${name}'`);
}

function digestCode(name) {
    const key = digestName(name);
    return key === 'sha1' ? 1 : key === 'sha384' ? 3 : key === 'sha512' ? 4 : 2;
}

function hmacName(name) {
    const key = String(name || 'sha256').toLowerCase().replace(/[-_]/g, '');
    if (key === 'sha1') return 'sha1';
    if (key === 'sha256') return 'sha256';
    if (key === 'sha512') return 'sha512';
    throw new Error(`mochicrypto: unsupported hmac digest '${name}'`);
}

export function randomBytes(size) {
    const n = Math.max(0, Number(size) || 0);
    if (!n) return new Buffer(0);
    return fromHex(ensureNative().randomHex(n));
}

export function createHash(algorithm) {
    const name = digestName(algorithm);
    const chunks = [];
    let done = false;
    return {
        update(data) {
            if (done) throw new Error('mochicrypto: digest already called');
            chunks.push(toBytes(data));
            return this;
        },
        digest(encoding) {
            done = true;
            const source = Buffer.concat(chunks);
            const fn = name === 'md5' ? ensureNative().md5Hex
                : name === 'sha1' ? ensureNative().sha1Hex
                : name === 'sha384' ? ensureNative().sha384Hex
                : name === 'sha512' ? ensureNative().sha512Hex
                : ensureNative().sha256Hex;
            const bytes = fromHex(fn(toHex(source)));
            return encoding ? bytes.toString(encoding) : bytes;
        },
    };
}

export function createHmac(algorithm, key) {
    const name = hmacName(algorithm);
    const chunks = [];
    let done = false;
    const secret = toHex(key);
    return {
        update(data) {
            if (done) throw new Error('mochicrypto: digest already called');
            chunks.push(toBytes(data));
            return this;
        },
        digest(encoding) {
            done = true;
            const source = toHex(Buffer.concat(chunks));
            const fn = name === 'sha1' ? ensureNative().hmacSha1Hex
                : name === 'sha512' ? ensureNative().hmacSha512Hex
                : ensureNative().hmacSha256Hex;
            const bytes = fromHex(fn(secret, source));
            return encoding ? bytes.toString(encoding) : bytes;
        },
    };
}

function hashBytes(name, bytes) {
    const api = ensureNative();
    const fn = name === 'md5' ? api.md5Hex
        : name === 'sha1' ? api.sha1Hex
        : name === 'sha384' ? api.sha384Hex
        : name === 'sha512' ? api.sha512Hex
        : api.sha256Hex;
    return fromHex(fn(toHex(bytes)));
}

function hmacBytes(name, key, data) {
    const api = ensureNative();
    if (name === 'sha1') return fromHex(api.hmacSha1Hex(toHex(key), toHex(data)));
    if (name === 'sha256') return fromHex(api.hmacSha256Hex(toHex(key), toHex(data)));
    if (name === 'sha512') return fromHex(api.hmacSha512Hex(toHex(key), toHex(data)));
    const blockSize = name === 'sha512' ? 128 : 64;
    const hlen = name === 'md5' ? 16 : 48;
    let secret = toBytes(key);
    if (secret.length > blockSize) secret = hashBytes(name, secret);
    const padded = new Uint8Array(blockSize);
    padded.set(secret.subarray(0, blockSize), 0);
    const inner = new Uint8Array(blockSize + data.length);
    const outer = new Uint8Array(blockSize + hlen);
    for (let i = 0; i < blockSize; i++) {
        inner[i] = padded[i] ^ 0x36;
        outer[i] = padded[i] ^ 0x5c;
    }
    inner.set(toBytes(data), blockSize);
    const innerHash = hashBytes(name, inner);
    outer.set(innerHash, blockSize);
    return hashBytes(name, outer);
}

export function pbkdf2Sync(password, salt, iterations, keylen, digest = 'sha256') {
    const name = digestName(digest);
    const rounds = Math.max(1, Number(iterations) || 1);
    const size = Math.max(1, Number(keylen) || 1);
    const hlen = name === 'md5' ? 16 : name === 'sha1' ? 20 : name === 'sha384' ? 48 : name === 'sha512' ? 64 : 32;
    const blocks = Math.ceil(size / hlen);
    const source = toBytes(password);
    const saltBytes = toBytes(salt);
    const out = new Uint8Array(blocks * hlen);
    for (let block = 1; block <= blocks; block++) {
        const seed = new Uint8Array(saltBytes.length + 4);
        seed.set(saltBytes, 0);
        new DataView(seed.buffer).setUint32(saltBytes.length, block, false);
        const state = hmacBytes(name, source, seed);
        const t = new Uint8Array(state);
        let current = new Uint8Array(state);
        for (let round = 1; round < rounds; round++) {
            current = hmacBytes(name, source, current);
            for (let i = 0; i < t.length; i++) t[i] ^= current[i];
        }
        out.set(t, (block - 1) * hlen);
    }
    return Buffer.from(out.subarray(0, size));
}

export function pbkdf2(password, salt, iterations, keylen, digest = 'sha256', callback) {
    if (typeof digest === 'function') {
        callback = digest;
        digest = 'sha256';
    }
    try {
        const result = pbkdf2Sync(password, salt, iterations, keylen, digest);
        if (callback) callback(null, result);
        return result;
    } catch (error) {
        if (callback) callback(error);
        else throw error;
        return undefined;
    }
}

export function timingSafeEqual(a, b) {
    return Number(ensureNative().timingSafeEqual(toHex(a), toHex(b))) === 1;
}

function cipherMode(algorithm) {
    const match = /^aes-(\d+)-(gcm|ctr|cbc)$/i.exec(String(algorithm || ''));
    if (!match) throw new Error(`mochicrypto: unsupported cipher '${algorithm}'`);
    return { bits: Number(match[1]), mode: match[2].toLowerCase() };
}

export function createCipheriv(algorithm, key, iv) {
    const spec = cipherMode(algorithm);
    const secret = toHex(key);
    const nonce = toHex(iv);
    const chunks = [];
    let aad = '';
    let authTag = null;
    let finished = false;
    return {
        mode: spec.mode,
        setAAD(value) {
            aad = toHex(value);
            return this;
        },
        setAutoPadding() {
            return this;
        },
        update(data) {
            if (finished) throw new Error('mochicrypto: cipher already finalized');
            chunks.push(toBytes(data));
            return new Buffer(0);
        },
        final() {
            finished = true;
            const api = ensureNative();
            const input = toHex(Buffer.concat(chunks));
            if (spec.mode === 'gcm') {
                const packed = JSON.parse(String(api.aesGcmEncryptHex(secret, nonce, aad, input)));
                authTag = fromHex(packed.tag);
                return fromHex(packed.data);
            }
            if (spec.mode === 'ctr') return fromHex(api.aesCtrCryptHex(secret, nonce, input));
            return fromHex(api.aesCbcEncryptHex(secret, nonce, input));
        },
        getAuthTag() {
            if (!authTag) throw new Error('mochicrypto: auth tag unavailable');
            return authTag;
        },
    };
}

export function createDecipheriv(algorithm, key, iv) {
    const spec = cipherMode(algorithm);
    const secret = toHex(key);
    const nonce = toHex(iv);
    const chunks = [];
    let aad = '';
    let tag = '';
    let finished = false;
    return {
        mode: spec.mode,
        setAAD(value) {
            aad = toHex(value);
            return this;
        },
        setAuthTag(value) {
            tag = toHex(value);
            return this;
        },
        setAutoPadding() {
            return this;
        },
        update(data) {
            if (finished) throw new Error('mochicrypto: decipher already finalized');
            chunks.push(toBytes(data));
            return new Buffer(0);
        },
        final() {
            finished = true;
            const api = ensureNative();
            const input = toHex(Buffer.concat(chunks));
            if (spec.mode === 'gcm') {
                const out = String(api.aesGcmDecryptHex(secret, nonce, aad, input, tag));
                if (!out && input) throw new Error('mochicrypto: GCM authentication failed');
                return fromHex(out);
            }
            if (spec.mode === 'ctr') return fromHex(api.aesCtrCryptHex(secret, nonce, input));
            return fromHex(api.aesCbcDecryptHex(secret, nonce, input));
        },
    };
}

function normalizeHashName(name) {
    const key = String(name || 'SHA-256').toLowerCase().replace(/[-_]/g, '');
    if (key === 'sha1') return 'sha1';
    if (key === 'sha256') return 'sha256';
    if (key === 'sha384') return 'sha384';
    if (key === 'sha512') return 'sha512';
    throw new Error(`mochicrypto: unsupported WebCrypto hash '${name}'`);
}

export const subtle = {
    async importKey(format, keyData, algorithm, extractable, usages) {
        if (String(format).toLowerCase() !== 'raw') throw new Error('mochicrypto: only raw importKey is supported');
        return {
            algorithm: String((algorithm && algorithm.name) || 'PBKDF2'),
            usages: Array.isArray(usages) ? usages.slice() : [],
            extractable: !!extractable,
            data: toBytes(keyData),
        };
    },
    async deriveBits(algorithm, key, length) {
        const name = String((algorithm && algorithm.name) || 'PBKDF2').toLowerCase();
        if (name !== 'pbkdf2') throw new Error(`mochicrypto: unsupported deriveBits '${name}'`);
        const digest = normalizeHashName(algorithm.hash);
        const bits = Math.max(1, Number(length) || 256);
        return pbkdf2Sync(key.data, algorithm.salt, algorithm.iterations, Math.ceil(bits / 8), digest);
    },
    async digest(algorithm, data) {
        const name = typeof algorithm === 'string' ? algorithm : algorithm.name;
        return createHash(normalizeHashName(name)).update(data).digest();
    },
};

export function getRandomValues(array) {
    const bytes = randomBytes(array.length);
    for (let i = 0; i < array.length; i++) array[i] = bytes[i];
    return array;
}

export function installGlobals() {
    if (native) {
        try {
            globalThis.crypto = { subtle, getRandomValues };
        } catch (e) {
            Object.defineProperty(globalThis, 'crypto', {
                value: { subtle, getRandomValues },
                configurable: true,
                writable: true,
            });
        }
        if (!globalThis.TextEncoder) {
            try {
                globalThis.TextEncoder = class MochiTextEncoder {
                    encode(value) {
                        return Buffer.from(String(value ?? ''), 'utf8');
                    }
                };
            } catch (e) {
                Object.defineProperty(globalThis, 'TextEncoder', {
                    value: class MochiTextEncoder {
                        encode(value) {
                            return Buffer.from(String(value ?? ''), 'utf8');
                        }
                    },
                    configurable: true,
                    writable: true,
                });
            }
        }
        if (!globalThis.TextDecoder) {
            try {
                globalThis.TextDecoder = class MochiTextDecoder {
                    decode(value) {
                        return Buffer.from(value).toString('utf8');
                    }
                };
            } catch (e) {
                Object.defineProperty(globalThis, 'TextDecoder', {
                    value: class MochiTextDecoder {
                        decode(value) {
                            return Buffer.from(value).toString('utf8');
                        }
                    },
                    configurable: true,
                    writable: true,
                });
            }
        }
    }
    return !!native;
}

installGlobals();

export const isNativeReady = () => !!native;
export const nativeError = () => nativeFailure;
export const nativeModule = () => native;

export class KeyObject { constructor(type, buf) { this.type = type; this._buf = Buffer.from(buf); } export() { return Buffer.from(this._buf); } }
export function createSecretKey(key) { return new KeyObject('secret', Buffer.from(toBytes(key))); }
export default {
    KeyObject,
    createSecretKey,
    randomUUID,
    randomFillSync,
    randomFill,
    get webcrypto() { return { subtle, getRandomValues }; },
    randomBytes,
    createHash,
    createHmac,
    pbkdf2,
    pbkdf2Sync,
    timingSafeEqual,
    createCipheriv,
    createDecipheriv,
    subtle,
    getRandomValues,
    installGlobals,
    isNativeReady,
};


export function randomUUID() {
    const b = randomBytes(16);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    const hex = Array.from(b).map(x=>x.toString(16).padStart(2,'0'));
    return hex.slice(0,4).join('')+'-'+hex.slice(4,6).join('')+'-'+hex.slice(6,8).join('')+'-'+hex.slice(8,10).join('')+'-'+hex.slice(10,16).join('');
}
export function randomFillSync(buf, offset=0, size) {
    const start = Number(offset) || 0;
    const end = size == null ? buf.length : start + Number(size);
    const bytes = randomBytes(end - start);
    for (let i = 0; i < bytes.length; i++) buf[start + i] = bytes[i];
    return buf;
}
export function randomFill(buf, offset, size, cb) {
    if (typeof offset === 'function') { cb = offset; offset = 0; size = buf.length; }
    if (typeof size === 'function') { cb = size; size = buf.length - (offset||0); }
    try { randomFillSync(buf, offset, size); if (cb) cb(null, buf); }
    catch(e) { if (cb) cb(e); else throw e; }
}
export const webcrypto = { subtle, getRandomValues };
